CREATE TABLE friendship(id UUID PRIMARY KEY,host_id UUID NOT NULL,guest_id UUID,host_name VARCHAR(30) NOT NULL,guest_name VARCHAR(30),status VARCHAR(20) NOT NULL,created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL,CHECK(guest_id IS NULL OR guest_id<>host_id));
CREATE INDEX friendship_host ON friendship(host_id);CREATE INDEX friendship_guest ON friendship(guest_id);
CREATE TABLE friend_message(seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,friendship_id UUID NOT NULL REFERENCES friendship(id) ON DELETE CASCADE,message_id VARCHAR(22) NOT NULL,sender VARCHAR(8) NOT NULL,iv VARCHAR(16) NOT NULL,ciphertext VARCHAR(8192) NOT NULL,created_at BIGINT NOT NULL,UNIQUE(friendship_id,message_id));
CREATE INDEX friend_message_room ON friend_message(friendship_id,seq);
CREATE TABLE friend_block(owner_id UUID NOT NULL,peer_id UUID NOT NULL,friendship_id UUID NOT NULL REFERENCES friendship(id),created_at BIGINT NOT NULL,PRIMARY KEY(owner_id,peer_id));

CREATE TABLE invite_decline (friendship_id UUID NOT NULL REFERENCES friendship(id), user_id UUID NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY(friendship_id,user_id));
